  summary = 'A foundational newsroom course in grammar, AP style, punctuation, usage, proofreading, concision, attribution, inclusive language, fact-checking, and digital copy quality. Students learn to edit for accuracy, clarity, fairness, consistency, and publication readiness across print, broadcast, web, newsletter, and social formats.',
  data = $gsjjson${"slug": "grammar-and-style-for-journalists", "title": "Grammar and Style for Journalists", "description": "A foundational newsroom course in grammar, AP style, punctuation, usage, proofreading, concision, attribution, inclusive language, fact-checking, and digital copy quality. Students learn to edit for accuracy, clarity, fairness, consistency, and publication readiness across print, broadcast, web, newsletter, and social formats.", "topics": [{"id": "e09ab0a3-bffa-4138-a20e-ec5ab325dcc0", "type": "topic", "title": "Parts of Speech for Newsroom Editing", "description": null, "children": [{"id": "7c6ff991-f51b-49c1-8965-0d52a40aa0b9", "type": "subtopic", "title": "Nouns, pronouns, and reference", "children": [{"id": "8e872765-3989-4e64-9873-7578969bad32", "type": "concept", "title": "Common and proper nouns"}, {"id": "a2af0537-82ab-46fa-977e-2ca62ed6f23c", "type": "concept", "title": "Pronoun antecedents"}, {"id": "a582a873-cf34-4947-ae00-4de0dde6990d", "type": "concept", "title": "Collective nouns"}, {"id": "fd784d2e-3765-4c1f-a8c1-b4327c13c6e8", "type": "concept", "title": "Titles and appositives"}], "description": "Students learn how names, titles, pronouns, and referents keep news copy clear, fair, and precise."}, {"id": "898429dd-4977-4d2d-8614-5ffd81abc7ec", "type": "subtopic", "title": "Verbs and verbals", "children": [{"id": "b8f92b9d-58a2-4f19-ae15-fc275c205bfc", "type": "concept", "title": "Finite verbs"}, {"id": "884a202a-a7a0-45cd-aa70-696820d3c8b2", "type": "concept", "title": "Participles"}, {"id": "7f34c4c5-a563-4b9a-bf6c-7b1e57e69548", "type": "concept", "title": "Gerunds"}, {"id": "922e3729-8ec2-46fc-93e3-aba6064ce6ae", "type": "concept", "title": "Infinitives"}], "description": "The point is to spot the action in a sentence and choose verb forms that create accurate time, voice, and attribution."}, {"id": "07aeec54-9cea-4485-b9a5-5f5239a3b95a", "type": "subtopic", "title": "Modifiers and connectors", "children": [{"id": "ec306162-a668-416f-99a6-564b1cb195bf", "type": "concept", "title": "Adjective order"}, {"id": "934f71a2-d652-4dc5-bd92-0d20fb91c5bc", "type": "concept", "title": "Adverb placement"}, {"id": "4fd4a6dc-898c-4d05-a974-eed9750d722b", "type": "concept", "title": "Prepositional phrases"}, {"id": "b6c0b92c-aafd-4649-ae34-8bbf04131353", "type": "concept", "title": "Coordinating and subordinating conjunctions"}], "description": "Students learn how adjectives, adverbs, prepositions, and conjunctions shape meaning and sentence flow."}]}, {"id": "eedc00bc-3d3e-478e-b721-092cb7b42625", "type": "topic", "title": "Sentence Structure and Syntax", "description": "Journalists need sentences that are clear under pressure. This section builds control over sentence patterns, coordination, subordination, and rhythm so students can write and edit without muddying the facts.", "children": [{"id": "b58f915c-204d-4d66-a306-380f23916c80", "type": "subtopic", "title": "Core sentence patterns", "children": [{"id": "e46a2608-f17a-48d8-a800-32eb4239e975", "type": "concept", "title": "Subject-verb-object order"}, {"id": "a671a294-50aa-4aa1-b627-2260f801e730", "type": "concept", "title": "Linking verbs"}, {"id": "dcbdb0b1-405c-4d96-8707-d26109f320d6", "type": "concept", "title": "Predicate complements"}, {"id": "e37588d2-0e9d-4a2a-b143-0adb5d8a678d", "type": "concept", "title": "Clause boundaries"}], "description": "Students identify subjects, predicates, objects, complements, and clauses as the framework of clear news prose."}, {"id": "1c0b7ed2-55eb-4400-b2ac-8c466cdd9c84", "type": "subtopic", "title": "Coordination and subordination", "children": [{"id": "ca73b4a8-54b0-413f-bf9b-d580a2080470", "type": "concept", "title": "Independent clauses"}, {"id": "f946c543-bdc1-432f-8e7a-8089e4ed361c", "type": "concept", "title": "Dependent clauses"}, {"id": "36e9163d-a3b5-49f9-b450-8e96ae8bcba3", "type": "concept", "title": "Compound sentences"}, {"id": "d2090685-01bf-4322-9074-9c8dd34d9457", "type": "concept", "title": "Complex sentences"}], "description": "Students learn how to combine ideas without creating run-ons, fragments, or distorted emphasis."}, {"id": "64fab98d-8da7-4d0b-92a7-b34a4bc0fcca", "type": "subtopic", "title": "Sentence rhythm", "children": [{"id": "1ce319a8-f81d-4ac5-b718-3b189268dafc", "type": "concept", "title": "Short declarative sentences"}, {"id": "bb5f3207-d63b-43a9-9410-d737454b202d", "type": "concept", "title": "Emphasis by placement"}, {"id": "4f9332e4-3595-4e87-b436-af6e53494a06", "type": "concept", "title": "Parallel openings"}, {"id": "f68f62f7-dd23-43f9-9ba3-54394319def9", "type": "concept", "title": "Sentence length control"}], "description": "The goal is to vary structure while preserving speed, accuracy, and readability."}]}, {"id": "228f5d0a-e254-4499-9cc9-171e84594ea7", "type": "topic", "title": "Common Grammar Errors and Newsroom Diagnostics", "description": null, "children": [{"id": "98a01c58-b731-4f4d-8411-b0acf581d70e", "type": "subtopic", "title": "Agreement and consistency", "children": [{"id": "a50bd002-2b12-4314-8cd1-fd761ad8cf3c", "type": "concept", "title": "Subject-verb agreement"}, {"id": "aea578b1-faeb-4f1b-9392-33c5e322cdb6", "type": "concept", "title": "Pronoun agreement"}, {"id": "ea55fdc3-c9da-4414-a09d-57ef255c428f", "type": "concept", "title": "Tense shifts"}, {"id": "7acb3353-cc3c-4c6a-b91b-9e1f82dd5e26", "type": "concept", "title": "Number consistency"}], "description": "Students practice checking whether subjects, verbs, pronouns, and tense choices line up across a story."}, {"id": "d9a67ac4-cf11-447b-9884-ca319e08f3cf", "type": "subtopic", "title": "Fragments, run-ons, and comma splices", "children": [{"id": "8579ad14-db08-4819-ae61-d2ab1fc39353", "type": "concept", "title": "Sentence fragments"}, {"id": "b7955b42-dddd-4b76-9e92-e7df8b1e9a1f", "type": "concept", "title": "Fused sentences"}, {"id": "16248394-5f84-4c4d-b96b-5a301a76536f", "type": "concept", "title": "Comma splices"}, {"id": "0b0972b0-8e84-4e19-874a-af06eaa4d15b", "type": "concept", "title": "Revision options"}], "description": "Students learn to repair broken or fused sentences without flattening useful voice."}, {"id": "fdbf7ed1-8a14-449b-950e-09488eb54bc0", "type": "subtopic", "title": "Dangling and misplaced modifiers", "children": [{"id": "93a7b08b-4c9b-46cc-8686-00663a04d0bb", "type": "concept", "title": "Introductory phrases"}, {"id": "5d9a6fe4-3874-48d4-bc0d-4372a8a6b280", "type": "concept", "title": "Only placement"}, {"id": "b6e639b8-a367-4080-9198-24a906fdd66d", "type": "concept", "title": "Squinting modifiers"}, {"id": "7a59f1cd-2575-48d6-b4e6-9cb909458ccb", "type": "concept", "title": "Cause-and-effect confusion"}], "description": "The point is to prevent accidental comedy, ambiguity, and factual distortion."}]}, {"id": "a19f844b-90ff-4bdc-a636-a00ed1007266", "type": "topic", "title": "Punctuation for Clarity and Pace", "description": null, "children": [{"id": "738a0cf5-bcdd-45cf-ac74-329b750e9751", "type": "subtopic", "title": "Commas and sentence logic", "children": [{"id": "a13a78cf-5ccc-45bc-a988-bc3a49232c8d", "type": "concept", "title": "Introductory elements"}, {"id": "1f135acb-7606-4f45-aa2b-2ad97e3498ee", "type": "concept", "title": "Nonessential clauses"}, {"id": "f0be96e6-099e-481e-935a-865666cdb3cb", "type": "concept", "title": "Series commas in AP"}, {"id": "be33db51-ca0c-4962-b8ab-fc025ec643b5", "type": "concept", "title": "Comma restraint"}], "description": "Students learn when commas help readers and when they slow or mislead them."}, {"id": "a0ba45ef-e943-4938-a7b5-a78f4c3ae4ef", "type": "subtopic", "title": "Colons, semicolons, dashes, and parentheses", "children": [{"id": "19f380f2-b5fc-4ab1-a455-1568fe748a92", "type": "concept", "title": "Colon setup"}, {"id": "be1c8a4d-39c1-40ac-91a7-8c0887140ef7", "type": "concept", "title": "Semicolon limits"}, {"id": "bda36c84-5ebd-4114-8fe9-30a6f12510f8", "type": "concept", "title": "Dash restraint"}, {"id": "ca57ebf8-7843-4278-bcf2-22d59d4bbda0", "type": "concept", "title": "Parenthetical context"}], "description": "Students learn to use stronger punctuation only when it clarifies structure or emphasis."}, {"id": "502409ef-db23-453c-ba44-076c9c2faf96", "type": "subtopic", "title": "Quotation punctuation", "children": [{"id": "08642f5d-c0a2-439d-bb0f-a095404a3855", "type": "concept", "title": "Quote marks"}, {"id": "d9dad63c-a46b-44fd-8450-9e53a47f61fa", "type": "concept", "title": "Attribution placement"}, {"id": "8dd6fdf0-bebe-460f-8ec9-cbdc977d2f47", "type": "concept", "title": "Ellipses"}, {"id": "44049280-d058-42ad-bb7c-8b8dea696d96", "type": "concept", "title": "Brackets"}], "description": "Students practice punctuating direct quotes, partial quotes, paraphrases, and attribution cleanly."}]}, {"id": "8fc54ace-2120-478b-bf0f-9b34a4e5b221", "type": "topic", "title": "AP Style Rules and Newsroom Conventions", "description": null, "children": [{"id": "73ad356c-590b-43ad-8ec6-aadbe3d499a5", "type": "subtopic", "title": "Names, titles, and identifiers", "children": [{"id": "a71ca53a-4f0a-49ae-9c9b-4439e48bd4b2", "type": "concept", "title": "First and second references"}, {"id": "895e3adb-1143-45ab-aadb-642d4a6b74b8", "type": "concept", "title": "Courtesy titles"}, {"id": "9d841650-0f3b-4acd-b066-08e7778ba78b", "type": "concept", "title": "Job titles"}, {"id": "600214aa-b2ff-472a-a59f-8381c3c80ddb", "type": "concept", "title": "Ages and hometowns"}], "description": "Students learn how to introduce people accurately and consistently while avoiding unnecessary labels."}, {"id": "4553558e-d511-4ab5-b873-a7a6c225a7a8", "type": "subtopic", "title": "Numbers, dates, addresses, and money", "children": [{"id": "134e60d8-852a-4047-9907-0b67b04a4477", "type": "concept", "title": "Numerals vs. words"}, {"id": "857bdbc0-3f37-4d0f-9901-c5a49300b7b1", "type": "concept", "title": "Dates and times"}, {"id": "ec44696e-02e5-47cf-8882-b3d9216ea55e", "type": "concept", "title": "Addresses"}, {"id": "5553f1a6-eef9-467f-8023-c2ee3fba4f4f", "type": "concept", "title": "Currency and percentages"}], "description": "Students practice high-frequency AP entries that often cause avoidable corrections."}, {"id": "27f539cd-5c08-4353-a962-e0c2d7fa315e", "type": "subtopic", "title": "Capitalization and abbreviations", "children": [{"id": "92267d1d-421e-4d6a-ab36-f089adabf3fb", "type": "concept", "title": "Formal titles"}, {"id": "a0963e81-4daf-4125-aff0-86cc46573f82", "type": "concept", "title": "Organizations"}, {"id": "84bb30e3-d55d-46d4-957e-40b29e4c386f", "type": "concept", "title": "States and nations"}, {"id": "1855908a-4f97-4cbf-8361-6cecbab15739", "type": "concept", "title": "Academic degrees"}], "description": "The point is to stop random capitalization and make abbreviations readable for broad audiences."}]}, {"id": "c14d1128-6b0e-49e2-a72b-1fd97e7e18c2", "type": "topic", "title": "Word Usage, Precision, and Meaning", "description": null, "children": [{"id": "3f62eb7d-6ecb-4670-ab95-a2dd8efedb09", "type": "subtopic", "title": "Concrete and specific language", "children": [{"id": "23312de0-7555-4a72-ae94-a59e96d8db57", "type": "concept", "title": "Specific nouns"}, {"id": "f89c3812-f496-40be-a815-066068fce1a2", "type": "concept", "title": "Strong verbs"}, {"id": "90e6e0ea-049b-4c33-bb17-e4e2a94fd2bf", "type": "concept", "title": "Avoiding jargon"}, {"id": "89899cc6-88df-4beb-876a-7321035165c3", "type": "concept", "title": "Avoiding cliches"}], "description": "Students learn to replace abstraction with observable facts and precise description."}, {"id": "ff700e87-4c6c-4bb6-bbdb-740c52daa746", "type": "subtopic", "title": "Usage traps and commonly confused words", "children": [{"id": "44b8052d-0114-4407-97ee-7f14f72bb063", "type": "concept", "title": "Affect/effect"}, {"id": "5e407a0e-d619-4baf-88c8-91d335515bbb", "type": "concept", "title": "Fewer/less"}, {"id": "b31f84d2-649e-457d-8efd-6c8d1a47bf5f", "type": "concept", "title": "Who/whom"}, {"id": "e2aded59-7f3a-4456-a897-3abd68369433", "type": "concept", "title": "That/which"}], "description": "Students build habits for checking words that appear often in news copy."}, {"id": "c70dafbb-518d-4137-8e44-110ae7754569", "type": "subtopic", "title": "Loaded language and unsupported claims", "children": [{"id": "747a239a-190c-4070-ae0a-ac56fad50d5f", "type": "concept", "title": "Alleged"}, {"id": "15b0a34a-16fe-410b-8acc-010d84a676ac", "type": "concept", "title": "Controversial"}, {"id": "1fbb2806-244a-483d-ba41-5f06e0fe0e38", "type": "concept", "title": "Historic"}, {"id": "6340eca3-fd00-48f9-b0a2-df924b3e2f69", "type": "concept", "title": "First/only/largest claims"}], "description": "The goal is to keep copy fair by separating fact, attribution, inference, and characterization."}]}, {"id": "80d18a7d-947b-422b-aeb2-da045ae27b90", "type": "topic", "title": "Editing for Clarity, Focus, and Flow", "description": null, "children": [{"id": "da7d3361-dcfd-4a73-b1e6-fc18e596fafe", "type": "subtopic", "title": "Story-level clarity", "children": [{"id": "c2b07447-6d3a-4539-8275-fcc57ffb09c0", "type": "concept", "title": "Nut graf clarity"}, {"id": "5bccc989-8361-4a38-b86c-9a7ba2f4ef53", "type": "concept", "title": "Transitions"}, {"id": "fdcb9a63-595b-46af-b681-01b0923c934c", "type": "concept", "title": "Context placement"}, {"id": "c57a4454-97b2-4935-baac-21d8b7ab9e1d", "type": "concept", "title": "Redundancy checks"}], "description": "Students learn to identify whether a piece has a clear point, logical order, and enough context."}, {"id": "e733845e-1fcd-46ff-8e68-8bda322a4cb9", "type": "subtopic", "title": "Paragraph and sentence revision", "children": [{"id": "79b22823-17ae-404a-8545-2c60ac6a1fb1", "type": "concept", "title": "Topic flow"}, {"id": "d6d8224b-1d9d-48d2-b29d-aa96f8494e0c", "type": "concept", "title": "Sentence combining"}, {"id": "52d73cc8-bd9d-46e3-b1f8-807a5f5183d7", "type": "concept", "title": "Sentence splitting"}, {"id": "fd577703-ccc6-45a3-bb38-6ce4ad4b7895", "type": "concept", "title": "Read-aloud editing"}], "description": "Students practice making copy cleaner without overediting voice or changing facts."}, {"id": "12a87cfe-40fc-447c-b595-c0129bc9e357", "type": "subtopic", "title": "Editor-reporter communication", "children": [{"id": "0f45d831-860f-4bf1-b63a-233e3bd49b5e", "type": "concept", "title": "Queries"}, {"id": "af458b1c-9e39-4699-80fe-01942c9a1198", "type": "concept", "title": "Change notes"}, {"id": "12afdd39-9937-46ca-ae34-4187e5313ded", "type": "concept", "title": "Respectful feedback"}, {"id": "7e6c82d1-0df1-4e45-b54d-2d98758cc1d7", "type": "concept", "title": "Escalation for factual concerns"}], "description": "The point is to make editing collaborative, specific, and accountable."}]}, {"id": "2ada7dd0-3401-4c8c-8251-28857c1694d2", "type": "topic", "title": "Conciseness and Deadline Revision", "description": null, "children": [{"id": "214b3889-42fa-4172-8506-267f4c9fd665", "type": "subtopic", "title": "Word economy", "children": [{"id": "44da6c14-e10f-4b0e-86b8-7a12bc0455db", "type": "concept", "title": "Empty openings"}, {"id": "e0b6491d-fabb-43d4-ac22-c49c780e89dd", "type": "concept", "title": "Redundant pairs"}, {"id": "48c43644-c20a-4e9f-9956-9ea1edc95628", "type": "concept", "title": "Nominalizations"}, {"id": "018cbfa4-01d0-46f1-8394-d4383127b180", "type": "concept", "title": "Prepositional pileups"}], "description": "Students identify filler, throat-clearing, duplication, and bureaucratic phrasing."}, {"id": "26791974-8e6a-4cc6-8ab2-9b70cd64a111", "type": "subtopic", "title": "Tight leads and summaries", "children": [{"id": "354fb98c-57e2-4f09-9029-8576a4925545", "type": "concept", "title": "Lead compression"}, {"id": "55b935fd-a72e-442c-9e2b-7e7ebdb0b0de", "type": "concept", "title": "Summary paragraphs"}, {"id": "078fd2cf-d413-4bd3-86c3-4c2c517b05c7", "type": "concept", "title": "Briefs"}, {"id": "cccbe618-6fa2-459e-bd46-d7cd3ff15cf4", "type": "concept", "title": "Updates"}], "description": "Students learn how to condense 